/*
 * A103698  Add 6 to each of the preceding digits, beginning with 0.
 * https://oeis.org/A103698
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  base, nonn
 * Formula:   not stated
 * Range:     u8 n <= 86, u16 n <= 86, u32 n <= 86, u64 n <= 86, u128 n <= 86,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * Sequence A103698: Add 6 to each of the preceding digits, beginning with 0.
 * a(0) = 0
 * Each term is generated by a breadth‑first traversal.  Starting from 0,
 * each node x yields child nodes equal to (digit+6) for every decimal
 * digit of x (most significant digit first).  The sequence lists the nodes
 * in the order they appear in this traversal.
 */
#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static data for incremental generation */
    static seq_t *queue = NULL;
    static size_t cap   = 0;      /* allocated capacity of queue   */
    static size_t sz    = 0;      /* number of terms stored       */
    static size_t next  = 0;      /* index of next node processed */

    /* initialise (first call) */
    if (queue == NULL) {
        cap = 16;
        queue = (seq_t *)malloc(sizeof(seq_t) * cap);
        queue[0] = (seq_t)0;    /* a(0) = 0 */
        sz   = 1;
        next = 0;
    }

    /* generate terms until we have a(n) */
    while (sz <= (size_t)n) {
        seq_t cur = queue[next];
        ++next;

        if (cur == 0) {                    /* special case for the root */
            seq_t child = (seq_t)6;
            if (sz == cap) {
                cap = cap * 2;
                queue = (seq_t *)realloc(queue, sizeof(seq_t) * cap);
            }
            queue[sz++] = child;
            continue;
        }

        /* decompose cur into its decimal digits (msb → lsb) */
        seq_t tmp   = cur;
        int  digits[32];
        int  dcnt = 0;
        while (tmp > (seq_t)0) {
            digits[dcnt++] = (int)(tmp % (seq_t)10);
            tmp /= (seq_t)10;
        }

        for (int i = dcnt - 1; i >= 0; --i) {
            seq_t child = (seq_t)(digits[i] + 6);   /* digit + 6 */
            if (sz == cap) {
                cap = cap * 2;
                queue = (seq_t *)realloc(queue, sizeof(seq_t) * cap);
            }
            queue[sz++] = child;
        }
    }

    return queue[(size_t)n];
}
